// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _runTest(uint256 depos1, uint256 depos2) internal {
        depos1 = bound(depos1, 0, 1000000000000000000000000000000);
        depos2 = bound(depos2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depos1 + depos2 >= depos1);
        vm.assume(address(this).balance >= depos1 + depos2);
        try c.Deposit{value: depos1}() {} catch { return; }
        try c.Deposit{value: depos2}() {} catch { return; }
        uint256 bal;
        try c.balances(address(this)) returns (uint256 __r) { bal = __r; } catch { return; }
        assertTrue(bal == depos1 + depos2);
    }

    function testFuzz_runTest(uint256 depos1, uint256 depos2) public {
        _runTest(depos1, depos2);
    }

    receive() external payable {}
}
